{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance should not have public IP",
      "resource": "aws_instance.ubuntu",
      "severity": "MEDIUM",
      "explanation": "The resource explicitly sets 'associate_public_ip_address' to true for one of the instances (count.index == 1), exposing it directly to the internet."
    },
    {
      "check_id": "AVD-AWS-0028",
      "title": "Instance does not require IMDS access to require a token",
      "resource": "aws_instance.ubuntu",
      "severity": "HIGH",
      "explanation": "The EC2 instance lacks an 'metadata_options' block enforcing HTTP tokens, leaving it vulnerable to SSRF attacks via the Instance Metadata Service (IMDSv1)."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"ubuntu\" {\n  count = 3\n  ami = data.aws_ami.ubuntu_14_04.image_id\n  instance_type = \"t2.micro\"\n  associate_public_ip_address = false\n  subnet_id = aws_subnet.my_subnet.id\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n}",
  "fix_summary": "Disabled public IP association for all instances by setting 'associate_public_ip_address' to false. Added 'metadata_options' block with 'http_tokens = required' to enforce IMDSv2 and prevent credential theft via SSRF."
}
